import {createContext, useContext, useEffect, useState} from 'react';
import {Button, Icon, Text, Select, Modal, TextInput, DropdownMenu, configure} from '@gravity-ui/uikit';
import {AsideHeader} from '@gravity-ui/navigation';
import {DashKit, type Config, type PluginWidgetProps} from '@gravity-ui/dashkit';
import {Chart} from '@gravity-ui/charts';
import {LayoutCells, ChartColumn, Persons, ShoppingBag, Gear, CircleQuestion, Plus, ArrowUpRight, ArrowRight, ArrowDownToLine, ArrowRotateRight, Ellipsis, Calendar, Grip, Bell, Magnifier, Xmark, Check, Sliders, Folder, ArrowChevronDown} from '@gravity-ui/icons';
import './styles.css';

configure({lang: 'ru'});
const titles: Record<string,string> = {revenue:'Выручка', orders:'Заказы', average:'Средний чек', conversion:'Конверсия', dynamics:'Динамика выручки', channels:'Источники продаж', transactions:'Последние заказы', goal:'Цель по выручке'};
const kinds = Object.keys(titles);
const initial: Config = {salt:'pulse',counter:8,aliases:{},connections:[],items:kinds.map((kind,i)=>({id:kind,type:'pulse-widget',namespace:'default',data:{kind},orderId:i})),layout:kinds.map((kind,i)=>({i:kind,x:i<4?i*3:i===4||i===6?0:8,y:i<4?0:i<6?4:12,w:i<4?3:i===4||i===6?8:4,h:i<4?4:8}))};
const DashboardContext = createContext({period:'30',edit:false,remove:(_id:string)=>{},detail:(_kind:string)=>{}});
const colors=['var(--g-color-base-brand)','var(--g-color-text-positive)','var(--g-color-base-info-heavy)','var(--g-color-base-generic-medium)'];
const channelNames=['Прямые переходы','Поисковые системы','Социальные сети','Другие'];
const values=[42,32,18,8];
const points=[35,43,39,31,50,44,57,48,45,58,76,68,80,70,66,89,73,84,68,74,94,87,107,92,99,89,115,105,113,124];
const rows=[['АК','Алексей Козлов','alexey.k@mail.ru','#1048','Сегодня, 14:32','12 490 ₽','Оплачен'],['МС','Мария Смирнова','m.smirnova@gmail.com','#1047','Сегодня, 14:18','8 750 ₽','Оплачен'],['ДВ','Дмитрий Волков','d.volkov@mail.ru','#1046','Сегодня, 13:56','24 900 ₽','В обработке'],['ЕП','Елена Петрова','elena.p@gmail.com','#1045','Сегодня, 13:41','6 200 ₽','Оплачен']];
function Metric({kind}:{kind:string}) {const {period}=useContext(DashboardContext);const index=kinds.indexOf(kind);const full=['2 458 320','1 284','1 915','3,62'];const short=['618 420','326','1 897','3,48'];return <><div className=\"metric-main\"><Text variant=\"display-1\">{(period==='7'?short:full)[index]}<span className=\"unit\">{index===0||index===2?' ₽':index===3?' %':''}</span></Text><div className=\"sparkline\"><Chart data={{series:{data:[{type:'area',name:titles[kind],color:index===3?'var(--g-color-base-info-heavy)':'var(--g-color-base-brand)',opacity:.1,data:[18,26,23,35,27,40,34,44,39,54,49,66].map((y,x)=>({x,y:y+Math.sin(x+index)*12}))}]},legend:{enabled:false},xAxis:{visible:false},yAxis:[{visible:false}],tooltip:{enabled:false}}}/></div></div><div className=\"metric-bottom\"><span className=\"growth\"><Icon data={ArrowUpRight} size={12}/> {['12,8','8,2','4,3','0,6'][index]}%</span><span>к прошлому периоду</span></div></>}
function Revenue(){const {period}=useContext(DashboardContext);const n=period==='7'?7:30;return <><div className=\"chart-summary\"><div><strong>{period==='7'?'618 420':'2 458 320'} ₽</strong><span className=\"growth\">↗ 12,8%</span></div><div className=\"legend\"><span><i/>Текущий период</span><span><i className=\"past\"/>Прошлый период</span></div></div><div className=\"revenue-chart\"><Chart data={{series:{data:[{type:'area',name:'Текущий период',color:colors[0],opacity:.09,lineWidth:2.5,data:points.slice(-n).map((y,x)=>({x,y}))},{type:'line',name:'Прошлый период',color:'var(--g-color-line-generic-active)',dashStyle:'dash',data:points.slice(-n).map((y,x)=>({x,y:y*.7+Math.cos(x)*8}))}]},legend:{enabled:false},xAxis:{type:'category',categories:Array.from({length:n},(_,i)=>"'`${i+1} июн`),grid:{enabled:false}},yAxis:[{min:0,max:150,ticks:{pixelInterval:50},labels:{format:{type:'"'custom',formatter:(v)=>"'`${v} тыс.`}},grid:{enabled:true}}]}}/></div></>}
function Channels(){return <><div className="donut"><Chart data={{series:{data:[{type:'"'pie',name:'Продажи',innerRadius:'76%',borderWidth:4,data:values.map((value,i)=>({value,name:channelNames[i],color:colors[i]})),dataLabels:{enabled:false}}]},legend:{enabled:false}}}/><div className=\"donut-label\"><strong>1 284</strong><span>всего заказов</span></div></div><div className=\"channel-list\">{channelNames.map((name,i)=><div key={name}><i style={{background:colors[i]}}/><span>{name}</span><b>{values[i]}%</b></div>)}</div></>}
function Transactions(){const {detail}=useContext(DashboardContext);return <><div className=\"table-wrap\"><table><thead><tr><th>Клиент</th><th>Заказ / дата</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r[0]} onClick={()=>detail("'`order-${i}`)} tabIndex={0} onKeyDown={e=>e.key==='"'Enter'&&detail("'`order-${i}`)}><td><span className={`customer-avatar avatar-${i}`}>{r[0]}</span><span className="customer-info"><b>{r[1]}</b><small>{r[2]}</small></span></td><td><b>{r[3]}</b><small>{r[4]}</small></td><td><b>{r[5]}</b></td><td><span className={`status ${i===2?'"'pending':''}"'`}><i/>{r[6]}</span></td></tr>)}</tbody></table></div><div className="table-footer"><span>Показаны 4 последних заказа</span><Button view="flat" size="s" onClick={()=>detail('"'orders')}>Все заказы <Icon data={ArrowRight} size={13}/></Button></div></>}
function Goal(){return <><div className=\"goal-subtitle\">Июнь 2025 <span>В процессе</span></div><div className=\"goal-value\">2 458 320 <span>/ 3 000 000 ₽</span></div><div className=\"goal-progress\"><span/></div><div className=\"goal-caption\"><strong>82% выполнено</strong><span>осталось 541 680 ₽</span></div><div className=\"goal-note\"><span className=\"goal-note-icon\"><Icon data={ChartColumn} size={20}/></span><div><b>Отличный темп"'!</b><p>Выручка на 12,8% выше, чем в прошлом месяце. Так держать!</p></div></div><div className="goal-bottom"><Icon data={Calendar} size={14}/> До конца месяца 6 дней</div></>}
function Widget({id,data}:PluginWidgetProps){const {edit,remove,detail}=useContext(DashboardContext);const kind=String(data.kind);return <section className={`widget widget-${kind}`}><div className="widget-header"><div className="widget-drag" title="Перетащить виджет"><span className="drag-dots"><Icon data={Grip} size={14}/></span><span>{titles[kind]}</span></div>{edit?<Button view="flat" size="xs" aria-label="Удалить виджет" onClick={()=>remove(id)}><Icon data={Xmark} size={14}/></Button>:<DropdownMenu size="s" items={[{text:'"'Подробнее',action:()=>detail(kind)},{text:'Удалить виджет',action:()=>remove(id),theme:'danger'}]} trigger={<Button view=\"flat\" size=\"xs\" aria-label={"'`Меню: ${titles[kind]}`}><Icon data={Ellipsis} size={17}/></Button>}/>}</div>{kinds.indexOf(kind)<4?<Metric kind={kind}/>:kind==='"'dynamics'?<Revenue/>:kind==='channels'?<Channels/>:kind==='transactions'?<Transactions/>:<Goal/>}</section>}
DashKit.setSettings({gridLayout:{cols:12,rowHeight:24,margin:[20,20],containerPadding:[0,0],compactType:'vertical'}});
DashKit.registerPlugins({type:'pulse-widget',defaultLayout:{w:4,h:8,minW:3,minH:4},renderer:props=><Widget {...props}/>});
function loadConfig(){try{const saved=JSON.parse(localStorage.getItem('pulse-layout')||'null');if(saved?.items?.every((v:{data:{kind:string}})=>kinds.includes(v.data.kind))&&Array.isArray(saved.layout))return saved as Config;}catch{}return initial;}

export function App(){const [config,setConfig]=useState<Config>(loadConfig);const [edit,setEdit]=useState(false);const [period,setPeriod]=useState('30');const [catalog,setCatalog]=useState(false);const [query,setQuery]=useState('');const [detail,setDetail]=useState('');const [tab,setTab]=useState('Обзор');const [toast,setToast]=useState('');const [compact,setCompact]=useState(window.innerWidth<1050);const [mobile,setMobile]=useState(window.innerWidth<700);const [updated,setUpdated]=useState('только что');
useEffect(()=>{try{localStorage.setItem('pulse-layout',JSON.stringify(config));}catch{setToast('Не удалось сохранить раскладку в браузере');}},[config]);useEffect(()=>{const resize=()=>{setMobile(window.innerWidth<700);setCompact(window.innerWidth<1050)};window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize)},[]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)}},[toast]);
const remove=(id:string)=>setConfig(c=>({...c,items:c.items.filter(i=>i.id"'!==id),layout:c.layout.filter(i=>i.i!==id)}));
const add=(kind:string)=>{const id=`${kind}-${Date.now()}`;setConfig(c=>({...c,counter:c.counter+1,items:[...c.items,{id,type:'"'pulse-widget',namespace:'default',data:{kind}}],layout:[...c.layout,{i:id,x:0,y:Math.max(0,...c.layout.map(i=>i.y+i.h)),w:kinds.indexOf(kind)<4?3:kind==='dynamics'||kind==='transactions'?8:4,h:kinds.indexOf(kind)<4?4:8}]}));setCatalog(false);setToast('Виджет добавлен на дашборд');};
const download=()=>{const blob=new Blob(['\\ufeffКлиент;Заказ;Дата;Сумма;Статус\\n'+rows.map(r=>r.slice(1).filter((_,i)=>i"'!==1).join('"';')).join('\\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pulse-orders.csv';a.click();URL.revokeObjectURL(a.href);setToast('Отчёт экспортирован');};
const visibleConfig=tab==='Обзор'?config:{...config,items:config.items.filter(i=>tab==='Продажи'?['revenue','orders','average','dynamics','transactions','goal'].includes(String(i.data.kind)):['conversion','channels','orders'].includes(String(i.data.kind))),layout:config.layout.filter(i=>config.items.some(it=>it.id===i.i&&(tab==='Продажи'?['revenue','orders','average','dynamics','transactions','goal']:['conversion','channels','orders']).includes(String(it.data.kind))))};
const page=<div className=\"page\"><header className=\"topbar\"><div className=\"breadcrumb\">Рабочее пространство <span>/</span><b>Мой дашборд</b><span className=\"private-badge\">Личный</span></div><div className=\"topbar-right\"><Button view=\"flat\" aria-label=\"Уведомления\" onClick={()=>setDetail('notifications')}><Icon data={Bell} size={19}/></Button><div className=\"top-divider\"/><Button view=\"flat\" onClick={()=>setDetail('profile')}><span className=\"profile-avatar\">АС</span></Button></div></header><main><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ БИЗНЕС В ЦИФРАХ</div><Text variant=\"display-1\" as=\"h1\">Мой дашборд <span className=\"title-dot\"/></Text><p>Всё важное — в одном месте. Настройте под себя.</p></div><div className=\"heading-actions\"><Button view=\"outlined\" size=\"l\" onClick={download}><Icon data={ArrowDownToLine} size={16}/> Экспорт</Button><Button view=\"action\" size=\"l\" onClick={()=>setCatalog(true)}><Icon data={Plus} size={17}/> Добавить виджет</Button></div></div><div className=\"dashboard-toolbar\"><div className=\"tabs\">{['Обзор','Продажи','Аудитория'].map(t=><Button key={t} view=\"flat\" className={tab===t?'tab active':'tab'} onClick={()=>setTab(t)}>{t}{t==='Обзор'&&<span className=\"tab-count\">{config.items.length}</span>}</Button>)}</div><div className=\"filters\"><div className=\"date-select\"><Icon data={Calendar} size={15}/><Select view=\"clear\" value={[period]} onUpdate={v=>setPeriod(v[0])} options={[{value:'30',content:'1–30 июня 2025'},{value:'7',content:'24–30 июня 2025'}]}/></div><Button view=\"outlined\" selected={edit} onClick={()=>{setEdit("'!edit);if(edit)setToast('"'Раскладка сохранена')}}><Icon data={edit?Check:Sliders} size={15}/>{edit?'Готово':'Настроить'}</Button><Button view=\"outlined\" aria-label=\"Обновить данные\" onClick={()=>{setUpdated(new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}));setToast('Данные обновлены')}}><Icon data={ArrowRotateRight} size={15}/></Button></div></div><div className={"'`layout-hint ${edit?'"'editing':''}"'`}><Icon data={edit?Grip:LayoutCells} size={16}/><span>{edit?'"'Режим настройки: перетаскивайте виджеты за заголовок и меняйте размер за нижний угол.':'Ваш дашборд — ваши правила.'} {"'!edit&&<span className="hint-secondary">Перемещайте и меняйте размер виджетов в режиме настройки.</span>}</span><Button view="flat" size="s" onClick={()=>edit?(setConfig(initial),setToast('"'Исходная раскладка восстановлена')):setEdit(true)}>{edit?'Сбросить раскладку':'Настроить'}<Icon data={ArrowRight} size={14}/></Button></div><DashboardContext.Provider value={{period,edit,remove,detail:setDetail}}><div className={edit?'dashboard-grid is-editing':'dashboard-grid'}>{visibleConfig.items.length===0?<div className=\"empty\"><Icon data={LayoutCells} size={40}/><Text variant=\"header-1\">Место для ваших идей</Text><p>Добавьте первый виджет, чтобы собрать свой дашборд.</p><Button view=\"action\" onClick={()=>setCatalog(true)}>Добавить виджет</Button></div>:mobile?<div className=\"mobile-widgets\">{visibleConfig.items.map(i=><div key={i.id} className={kinds.indexOf(String(i.data.kind))<4?'mobile-metric':'mobile-large'}><Widget {...({id:i.id,data:i.data} as PluginWidgetProps)}/></div>)}</div>:<DashKit config={visibleConfig} editMode={edit&&tab==='Обзор'} noOverlay draggableHandleClassName=\"widget-drag\" onChange={({config:c})=>setConfig(c)}/>}</div></DashboardContext.Provider><footer className=\"page-footer\"><span><i/> Обновлено {updated}<span className=\"footer-separator\">·</span>Демонстрационные данные</span><span>Сделано для ясных решений <span className=\"mini-logo\">✳</span></span></footer></main></div>;
return <><AsideHeader compact={compact} onChangeCompact={setCompact} hideCollapseButton logo={{text:'пульс',icon:ChartColumn,iconSize:26,textSize:26,iconClassName:'brand-icon'}} subheaderItems={[{item:{id:'workspace',title:'Моя компания',icon:Folder},onItemClick:()=>setDetail('workspace')}]} menuItems={[{id:'dash',title:'Дашборд',icon:LayoutCells,current:true,onItemClick:()=>setTab('Обзор')},{id:'analytics',title:'Аналитика',icon:ChartColumn,onItemClick:()=>setTab('Продажи')},{id:'reports',title:'Отчёты',icon:Folder,onItemClick:()=>setDetail('reports')},{id:'team',title:'Команда',icon:Persons,onItemClick:()=>setDetail('team')}]} renderFooter={()=> <div className=\"sidebar-footer\">{"'!compact&&<div className="sidebar-tip"><span className="tip-icon">✧</span><b>Больше возможностей</b><p>Ваши данные. Ваш порядок.<br/>Ваш идеальный дашборд.</p><Button view="outlined" width="max" onClick={()=>setCatalog(true)}>Открыть виджеты <Icon data={ArrowUpRight} size={14}/></Button></div>}<Button view="flat" width="max" onClick={()=>{setEdit(true);setToast('"'Режим настройки включён')}}><Icon data={Gear} size={18}/>{"'!compact&&'"'Настройки'}</Button><Button view=\"flat\" width=\"max\" onClick={()=>setDetail('help')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button>{"'!compact&&<div className="workspace-user"><span className="profile-avatar">АС</span><div><b>Александр Смирнов</b><small>Личное пространство</small></div><Icon data={ArrowChevronDown} size={12}/></div>}</div>} renderContent={()=>page}/><Modal open={catalog} onOpenChange={setCatalog}><div className="modal-body"><div className="modal-heading"><Text variant="header-2">Добавить виджет</Text><Button view="flat" onClick={()=>setCatalog(false)} aria-label="Закрыть"><Icon data={Xmark}/></Button></div><p className="muted">Выберите показатели, которые важны для вас.</p><TextInput value={query} onUpdate={setQuery} placeholder="Найти виджет" startContent={<Icon data={Magnifier}/>}/><div className="catalog">{kinds.filter(k=>titles[k].toLowerCase().includes(query.toLowerCase())).map(k=><div className="catalog-item" key={k}><span className="catalog-icon"><Icon data={k==='"'orders'||k==='transactions'?ShoppingBag:k==='channels'?Persons:ChartColumn} size={23}/></span><div><b>{titles[k]}</b><small>{kinds.indexOf(k)<4?'Ключевой показатель':'Аналитический виджет'}</small></div><Button view=\"outlined\" onClick={()=>add(k)} aria-label={"'`Добавить: ${titles[k]}`}><Icon data={Plus}/></Button></div>)}{!kinds.some(k=>titles[k].toLowerCase().includes(query.toLowerCase()))&&<p>Ничего не найдено. Попробуйте другой запрос.</p>}</div></div></Modal><Modal open={Boolean(detail)} onOpenChange={open=>!open&&setDetail('"'')}><div className=\"modal-body\"><div className=\"modal-heading\"><Text variant=\"header-2\">{titles[detail]||({notifications:'Уведомления',profile:'Ваш профиль',workspace:'Моя компания',reports:'Отчёты',team:'Команда',help:'Как настроить дашборд',orders:'Заказы'} as Record<string,string>)[detail]||'Информация о заказе'}</Text><Button view=\"flat\" onClick={()=>setDetail('')} aria-label=\"Закрыть\"><Icon data={Xmark}/></Button></div>{detail.startsWith('order-')?<div className=\"order-details\">{rows[Number(detail.split('-')[1])].slice(1).map((v,i)=><p key={i}>{v}</p>)}</div>:detail==='help'?<><p>Нажмите «Настроить», затем перетащите виджет за заголовок на новое место. Потяните нижний правый угол, чтобы изменить его размер.</p><p>Добавляйте виджеты из каталога и удаляйте лишние. Раскладка автоматически сохраняется в этом браузере.</p></>:detail==='notifications'?<p>Всё актуально. Новых уведомлений нет.</p>:detail==='profile'||detail==='team'||detail==='workspace'?<><p><b>Александр Смирнов</b></p><p>Владелец · Моя компания</p><p className=\"muted\">Личное рабочее пространство</p></>:detail==='reports'||detail==='orders'||detail==='transactions'?<><p>Отчёт по последним заказам за выбранный период.</p>{rows.map(r=><p key={r[0]}>{r[3]} · {r[1]} · {r[5]}</p>)}<Button view=\"action\" onClick={download}>Скачать CSV</Button></>:<><p>Демонстрационные показатели за {period==='7'?'последние 7 дней':'июнь 2025'}.</p><p>{detail==='goal'?'Цель: 3 000 000 ₽. Выполнено 82%.':detail==='channels'?'Прямые переходы — 42%, поиск — 32%, социальные сети — 18%, другие — 8%.':"'`${titles[detail]}: ${detail==='"'orders'?'1 284':detail==='average'?'1 915 ₽':detail==='conversion'?'3,62%':'2 458 320 ₽'}"'`}</p><p className="muted">Данные приведены для демонстрации возможностей дашборда.</p></>}</div></Modal>{toast&&<div role="status" className="toast"><Icon data={Check} size={17}/>{toast}</div>}</>;
}
EOF
npm run build'

