p='src/App.tsx'
s=open(p).read().replace(\"dashStyle:'dash'\",\"dashStyle:'Dash'\").replace(\"labels:{format:{type:'custom',formatter:(v)=>"'`${v} тыс.`}},",'"'').replace(\"type:'pie',name:'Продажи',\",\"type:'pie',\").replace(' trigger={<Button',' switcher={<Button').replace(\"item:{id:'workspace',title:'Моя компания',icon:Folder},onItemClick:()=>setDetail('workspace')\",\"item:{id:'workspace',title:'Моя компания',icon:Folder,onItemClick:()=>setDetail('workspace')}\").replace('rowHeight:24','rowHeight:20').replace('DashKit.registerPlugins({','DashKit.reloadPlugins({')
open(p,'w').write(s)
PY
